import{_ as r}from"./peer-selection-ba262d1a.js";import{_ as s}from"./plugin-vue_export-helper-c27b6911.js";import{r as n,o as a,c,d as t,e,b as o,w as i,a as l,f as u}from"./app-901c4b09.js";const h={},p=t("strong",null,"对方发来的消息，应该进哪个会话？我发出去的消息，又该落到对方的哪个工作区、哪个会话？",-1),g=t("p",null,[e('最初的做法是"自动注入到最近一次调用的会话"——不可控，也解释不清。现在改成了'),t("strong",null,"用户选择"),e("，而且选择由工具内部强制，不靠模型自觉。")],-1),_=u(`<h2 id="_1-为什么要-选会话" tabindex="-1"><a class="header-anchor" href="#_1-为什么要-选会话" aria-hidden="true">#</a> 1. 为什么要&quot;选会话&quot;</h2><p>早期的链路是这样的：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>link 发消息 → hub 找&quot;最近向这个 link 发过 peer_ask 的本地会话&quot; → 注入
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这有三个问题：</p><ul><li>多个本地会话都问过同一个 peer 时，<strong>最后调用的赢</strong>，回复可能进错会话</li><li>peer 从没被问过的会话发消息时，没有&quot;发起者&quot;，只能进全局兜底</li><li>对端有几十个会话，用户根本不知道消息会落到哪个</li></ul><p>所以把&quot;目标&quot;变成显式选择：<strong>工作区 + 会话</strong>。</p><h2 id="_2-发送侧-一张卡片选两件事" tabindex="-1"><a class="header-anchor" href="#_2-发送侧-一张卡片选两件事" aria-hidden="true">#</a> 2. 发送侧：一张卡片选两件事</h2><p>发送前的流程：</p><figure><img src="`+r+`" alt="发送与接收的选择流程" tabindex="0" loading="lazy"><figcaption>发送与接收的选择流程</figcaption></figure><ol><li><code>peer_targets(peer)</code> 拿到对端信息： <ul><li><code>workspaces</code>：对端 dsh 注册的工作区列表</li><li><code>sessions</code>：全部会话（活跃 + 已落盘），带<strong>标题</strong>和目录</li></ul></li><li>工具内部调用 <code>userQuestions.ask</code>，一次问两个问题： <ul><li>远端工作区：已有工作区 / 新建目录（输入绝对路径）</li><li>远端会话：已有会话（显示 <code>标题 · 目录</code>）/ 新建会话（输入名字）</li></ul></li><li>用户点完，工具拿到 <code>remoteDir</code> 和 <code>remoteSessionId</code>，才继续发送</li></ol><p>关键点：<strong>这一步在工具内部执行</strong>。<code>peer_ask</code> / <code>peer_send</code> 的 <code>execute</code> 里先 <code>await pickRemoteTarget(...)</code>，答案没回来就不会调用 <code>hub.ask</code>。模型没有办法&quot;跳过提问直接发&quot;——除非显式传 <code>remoteDir</code> + <code>session</code>/<code>remoteSessionId</code>（运维指令用）。</p><h2 id="_3-接收侧-先落-pending-再绑定" tabindex="-1"><a class="header-anchor" href="#_3-接收侧-先落-pending-再绑定" aria-hidden="true">#</a> 3. 接收侧：先落 pending，再绑定</h2><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>macmini peer_send
  → hub: peer/reply
  → pending 入队（同时写 $DSH_HOME/peer-pending.json）
  → 唤醒当前会话，注入&quot;待绑定&quot;提示（带 peer / 远端会话 / 工作区）
  → 当前会话：peer_pending + ask_user_question
       一张卡片：本地现有会话 / 新建会话
  → peer_bind(id, sessionId | new)
  → 注入该会话并唤醒
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>几个细节：</p><ul><li><strong>不自动注入</strong>：消息先停在 pending，避免&quot;落到不知道哪个会话&quot;</li><li><strong>落盘</strong>：入队和绑定都写文件，hub 重启后 pending 还在</li><li><strong>竞态兜底</strong>：绑定成功后，若旧提示延迟到达，处理前先查 <code>peer_pending</code>；为空就只回&quot;已处理&quot;，不再弹第二次选择</li></ul><h2 id="_4-远端会话为什么在-gui-里看不见" tabindex="-1"><a class="header-anchor" href="#_4-远端会话为什么在-gui-里看不见" aria-hidden="true">#</a> 4. 远端会话为什么在 GUI 里看不见</h2><p>这是踩得最久的一个坑。macmini 的 dsh GUI 按 <strong>workspace</strong> 列会话，并且用 <strong>session header 的 cwd</strong> 过滤。peer 会话最初是 link 用默认目录创建的：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>session header cwd = /Users/patrick
workspace 列表里没有 /Users/patrick  → 会话不可见
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>修复分两步：</p><ol><li>发送时把用户选的目录通过 <code>peer/prepare-session</code> 提前告诉 link，<strong>创建会话时直接用这个 cwd 作为 header cwd</strong></li><li>会话创建后，link 找到 cwd 对应的工作区（没有就创建），<code>attachSession</code></li></ol><p>对已存在的旧会话，header cwd 改不了，所以仍可能不可见——新会话才会落到你选的目录。</p><h2 id="_5-会话标题从哪来" tabindex="-1"><a class="header-anchor" href="#_5-会话标题从哪来" aria-hidden="true">#</a> 5. 会话标题从哪来</h2><p>卡片的会话列表要显示&quot;和 GUI 里一样的标题&quot;，来源分两种：</p><table><thead><tr><th>会话状态</th><th>标题来源</th></tr></thead><tbody><tr><td>活跃（在 link 进程里）</td><td><code>sessionTitle.get(session).title</code></td></tr><tr><td>已落盘但未打开</td><td><code>sessionProjectionCache.cachedSnapshot(header)</code> 的 title 投影</td></tr></tbody></table><p>合并后按 <code>createdAt</code> 倒序，最多 30 个；卡片里取最近 8 个，避免太长。</p><h2 id="_6-这一路踩的坑" tabindex="-1"><a class="header-anchor" href="#_6-这一路踩的坑" aria-hidden="true">#</a> 6. 这一路踩的坑</h2><table><thead><tr><th>现象</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td>卡片里没有已有会话</td><td>hub 只列自己内存里的 <code>link.sessions</code>，重启即空</td><td>向 link 查 <code>peer/sessions</code>，合并持久化会话</td></tr><tr><td>选了目录，远端还是 <code>/Users/patrick</code></td><td><code>working-directory/set</code> 改的是 projection，header cwd 没变；且 SDK server 的 <code>ctx.workingDirectory</code> 需要 inject</td><td>link 自己实现 set（<code>ctx.get</code>），并在创建前用 <code>peer/prepare-session</code> 定 cwd</td></tr><tr><td>发送前弹了卡片，显式传参也弹</td><td>选择函数无条件调用</td><td>显式 <code>remoteDir</code> + <code>session</code>/<code>remoteSessionId</code> 时跳过</td></tr><tr><td>hub 重启后待绑定消息没了</td><td>pending 只在内存</td><td>落盘 <code>peer-pending.json</code></td></tr><tr><td>绑定后旧提示又弹一次选择</td><td>提示已入队，绑定无法撤回</td><td>处理前检查 pending；为空只回&quot;已处理&quot;</td></tr></tbody></table><h2 id="_7-还没做的" tabindex="-1"><a class="header-anchor" href="#_7-还没做的" aria-hidden="true">#</a> 7. 还没做的</h2><ul><li><strong>应用内原生卡片</strong>：现在的选择卡片是 DSH 的 <code>ask_user_question</code> / <code>userQuestions.ask</code> 渲染的，已经比较接近原生；但&quot;选择工作区 + 会话&quot;目前是<strong>两个问题的同一张卡</strong>，不是专门的 picker 组件</li><li><strong>代码级权限约束</strong>：peer 来源的 turn 仍然用用户会话的权限；应该改成受限 preset，特权操作必须真人批准</li><li><strong>远端会话的 header 迁移</strong>：旧会话的 cwd 无法改，只能新建</li></ul><h2 id="_8-小结" tabindex="-1"><a class="header-anchor" href="#_8-小结" aria-hidden="true">#</a> 8. 小结</h2><ul><li>目标选择要<strong>显式</strong>：工作区、会话都让用户点，不猜&quot;最近一次&quot;</li><li>强制要落在<strong>工具内部</strong>：<code>userQuestions.ask</code> 在 <code>execute</code> 里，模型跳不过</li><li>可见性依赖 <strong>header cwd + workspace attach</strong>，不是&quot;建了会话就自动出现&quot;</li><li>跨进程的状态（pending）要<strong>持久化</strong>，否则一次重启就丢</li></ul>`,31);function m(b,v){const d=n("RouterLink");return a(),c("div",null,[t("p",null,[e("上一篇写了 "),o(d,{to:"/architecture/dsh-peer-steer.html"},{default:i(()=>[e("steer 与 cancel")]),_:1}),e("。这一篇解决另一个问题："),p]),g,t("blockquote",null,[t("p",null,[e("English version: "),o(d,{to:"/en/architecture/dsh-peer-selection.html"},{default:i(()=>[e("Putting the choice on a session")]),_:1})])]),l(" more "),_])}const f=s(h,[["render",m],["__file","dsh-peer-selection.html.vue"]]);export{f as default};
